package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
/** Home cards share the existing title and episode editors; status writes touch one field. */
final class HomeResumeView extends LinearLayout {
 interface Actions {void details(JSONObject item,Button button);void progress(JSONObject item,AccountRepository.Callback callback);void episodes(JSONObject item,Runnable saved);void status(JSONObject item,String status,AccountRepository.Callback callback);void explore(String kind);}
 private final JSONArray source;private final Actions actions;private final LinearLayout filters,list;private String filter="all";private int generation;private final String owner;
 HomeResumeView(Context c,JSONArray rows,Actions events){super(c);source=rows;actions=events;owner=SessionPreferences.get(c).getString("user_id","");setOrientation(VERTICAL);addView(text("Continuar de onde parei",22));HorizontalScrollView scroll=new HorizontalScrollView(c);scroll.setHorizontalScrollBarEnabled(false);filters=new LinearLayout(c);scroll.addView(filters);addView(scroll);list=new LinearLayout(c);list.setOrientation(VERTICAL);addView(list);String[] keys={"all","jogos","filmes","series","animes"},labels={"Todos","Jogos","Filmes","Séries","Animes"};for(int i=0;i<keys.length;i++){final String key=keys[i];Button b=button(labels[i]);b.setTag(key);filters.addView(b);b.setOnClickListener(v->{filter=key;render();});}render();}
 private boolean current(int g){return generation==g&&isAttachedToWindow()&&owner.equals(SessionPreferences.get(getContext()).getString("user_id",""));}
 private TextView text(String value,int size){return NativeSheet.text(getContext(),value,size,0xffeee8fa);}
 private Button button(String label){Button b=new Button(getContext());b.setText(label);AppStyle.button(b,false);return b;}
 private int dp(int n){return AppStyle.dp(this,n);}
 private void render(){int g=++generation;list.removeAllViews();for(int i=0;i<filters.getChildCount();i++){Button b=(Button)filters.getChildAt(i);boolean selected=filter.equals(b.getTag());b.setSelected(selected);b.setContentDescription(b.getText()+(selected?", selecionado":""));AppStyle.button(b,selected);}JSONArray rows=HomeResumePolicy.select(source,filter);if(rows.length()==0){list.addView(text("Nenhum título em andamento nesta categoria.",14));Button explore=button("Explorar biblioteca");list.addView(explore);explore.setOnClickListener(v->actions.explore(filter));return;}for(int i=0;i<rows.length();i++){JSONObject item=rows.optJSONObject(i);boolean game=HomeResumePolicy.kind(item).equals("jogos"),episodes=HomeResumePolicy.kind(item).equals("series")||HomeResumePolicy.kind(item).equals("animes");LinearLayout card=new LinearLayout(getContext());card.setOrientation(VERTICAL);card.setPadding(dp(14),dp(14),dp(14),dp(14));card.setBackground(AppStyle.surface(card,NativeTheme.panelDark(getContext()),20));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(12),0,0);list.addView(card,cp);LinearLayout summary=new LinearLayout(getContext());card.addView(summary);ImageView image=new CardCoverImage(getContext());summary.addView(image,new LinearLayout.LayoutParams(dp(76),dp(114)));MobileArtworkLoader.load(image,item,!game,true);LinearLayout info=new LinearLayout(getContext());info.setOrientation(VERTICAL);info.setPadding(dp(12),0,0,0);summary.addView(info,new LinearLayout.LayoutParams(0,-2,1));TextView kind=text(HomeResumePolicy.label(item).toUpperCase(java.util.Locale.ROOT),11);kind.setTextColor(NativeTheme.accent(getContext()));info.addView(kind);TextView title=text(item.optString("nome","Título"),17);title.setTypeface(null,android.graphics.Typeface.BOLD);info.addView(title);TextView progress=text(game?HoursDisplay.detailed(item.opt("horas")):item.optString("status"),12);info.addView(progress);long stamp=MessageTime.epoch(item.optString("updated_at"));TextView updated=text(stamp>0?"Atualizado em "+android.text.format.DateFormat.getDateFormat(getContext()).format(new java.util.Date(stamp)):"Sem data de atualização",11);updated.setTextColor(0xffa99bbc);info.addView(updated);TextView feedback=text("",12);feedback.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);card.addView(feedback);Button details=button("Ver detalhes");card.addView(details);details.setOnClickListener(v->actions.details(item,details));if(episodes){Runnable reload=()->loadProgress(item,progress,g);post(reload);Button edit=button("Atualizar episódios");card.addView(edit);edit.setOnClickListener(v->actions.episodes(item,reload));}Button status=button("Alterar status");card.addView(status);status.setOnClickListener(v->{String[] labels={"Pausado",game?"Zerado":"Assistido"},values={"⏸️ Pausado",game?"✅ Zerado":"✅ Assistido"};new android.app.AlertDialog.Builder(getContext()).setTitle("Status de "+item.optString("nome")).setItems(labels,(dialog,index)->{status.setEnabled(false);feedback.setText("Salvando…");actions.status(item,values[index],(saved,error)->{if(!isAttachedToWindow()||!owner.equals(SessionPreferences.get(getContext()).getString("user_id","")))return;if(error!=null){if(!current(g))return;feedback.setText(error);Button refresh=button("Atualizar início");card.addView(refresh);refresh.setOnClickListener(v2->actions.explore("refresh"));return;}try{item.put("status",values[index]);}catch(JSONException ignored){}render();Toast.makeText(getContext(),"Status atualizado",Toast.LENGTH_SHORT).show();});}).setNegativeButton("Cancelar",null).show();});}}
 private void loadProgress(JSONObject item,TextView target,int g){target.setText("Carregando episódios…");actions.progress(item,(rows,error)->{if(!current(g))return;JSONObject p=rows==null?null:rows.optJSONObject(0);target.setText(error!=null||p==null?"Progresso indisponível.":"Temporada "+p.optInt("temporada",1)+" · Episódio "+p.optInt("episodio",0));});}
}
